Sure! Below is a Python implementation of a custom iterator class that generates a sequence of prime numbers. After defining the class, we'll use it to generate the first 100 prime numbers and save them to a file named `prime_iterator.txt`.

```python
class PrimeIterator:
    def __init__(self, limit):
        self.limit = limit
        self.count = 0
        self.current = 1

    def __iter__(self):
        return self

    def __next__(self):
        if self.count >= self.limit:
            raise StopIteration
        self.current += 1
        while not self.is_prime(self.current):
            self.current += 1
        self.count += 1
        return self.current

    @staticmethod
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

# Generate the first 100 prime numbers
prime_iterator = PrimeIterator(100)
primes = list(prime_iterator)

# Save the prime numbers to a file
with open('prime_iterator.txt', 'w') as file:
    for prime in primes:
        file.write(f"{prime}\n")

print("The first 100 prime numbers have been saved to prime_iterator.txt.")
```

